    var topic = Object.assign({aliases:[],relatedTopics:[],prerequisites:[],labs:[],curriculumTags:['Foundation','CBSE / ICSE','NEET','AP Biology','A-Level','IB','Introductory University'],difficulty:'school',status:'complete',depth:{entry:'Foundation',mechanism:'High school / introductory college',advanced:'Introductory university extensions'}},meta);
    topic.explanations = {};
